  padding:10px 12px;transition:background-color var(--t) var(--ease)}
.q-mobar-call{background:var(--navy-900);color:#fff}
.q-mobar-call:hover,.q-mobar-call:active{background:var(--navy-700);color:#fff}
.q-mobar-quote{background:var(--red);color:#fff}
.q-mobar-quote:hover,.q-mobar-quote:active{background:var(--red-700)}
.q-mobar .ic{width:18px;height:18px;flex:none}
@media (max-width:420px){
  .q-mobar a,.q-mobar button,.q-mobar label{font-size:.86rem;gap:.4em}
