/* ---------- trust signals live inside the hero card ---------- */
.hero-card .proof{grid-template-columns:1fr;border-top:0;padding:0;margin:0;gap:0}
.hero-card .proof li{border-left:0;border-top:1px solid rgba(255,255,255,.13);padding:13px 0;gap:.7em;
  font-size:.8rem;line-height:1.45;align-items:center}
.hero-card .proof li:first-child{border-top:0;padding-top:4px}
.hero-card .proof li:last-child{padding-bottom:0}
.hero-card .proof .ic-md{width:30px;height:30px;padding:7px;margin-top:0}
.hero-card .proof b{font-size:.9rem;margin-bottom:0}
