/* ============================================================
   v6: live ticker bar, animated call button, shining headline
   ============================================================ */

/* ---------- top ticker bar ---------- */
.utility{background:#0a1020;overflow:hidden}
.utility .wrap{display:flex;align-items:center;gap:clamp(14px,2vw,26px);padding-block:9px;max-width:none;
  padding-inline:clamp(14px,3vw,34px)}
.live-pill{position:relative;display:inline-flex;align-items:center;gap:.55em;flex:none;margin:0;
  font-family:var(--ff-head);font-weight:700;font-size:.74rem;letter-spacing:.13em;text-transform:uppercase;
  color:#7ef0a6;background:rgba(34,197,94,.14);border:1px solid rgba(34,197,94,.42);
  border-radius:var(--r-pill);padding:7px 15px 7px 13px;white-space:nowrap;
  animation:pill-breathe 3s var(--ease) infinite}
@keyframes pill-breathe{
  0%,100%{box-shadow:0 0 0 0 rgba(34,197,94,.34);border-color:rgba(34,197,94,.42)}
  50%{box-shadow:0 0 0 7px rgba(34,197,94,0);border-color:rgba(34,197,94,.8)}
}
.live-dot{width:8px;height:8px;border-radius:50%;background:#2ee06a;flex:none;position:relative;
  box-shadow:0 0 9px rgba(46,224,106,.95)}
.live-dot::after{content:"";position:absolute;inset:-5px;border-radius:50%;border:1.5px solid rgba(46,224,106,.75);
  animation:dot-ping 2.1s var(--ease) infinite}
@keyframes dot-ping{0%{transform:scale(.55);opacity:1}75%,100%{transform:scale(1.5);opacity:0}}
.ticker{position:relative;flex:1 1 auto;min-width:0;overflow:hidden;
  -webkit-mask:linear-gradient(90deg,transparent 0,#000 7%,#000 93%,transparent 100%);
  mask:linear-gradient(90deg,transparent 0,#000 7%,#000 93%,transparent 100%)}
.ticker-track{display:flex;align-items:center;gap:0;width:max-content;animation:tick-roll 46s linear infinite}
.ticker-track span{display:inline-flex;align-items:center;white-space:nowrap;font-size:.8rem;color:#c3d1ea;
  padding:0 clamp(18px,2vw,30px)}
.ticker-track span::after{content:"";width:6px;height:6px;border-radius:50%;background:var(--red);
  margin-left:clamp(18px,2vw,30px);flex:none}
@keyframes tick-roll{from{transform:translateX(0)}to{transform:translateX(-50%)}}
.utility:hover .ticker-track{animation-play-state:paused}
@media (max-width:860px){
  .utility .wrap{gap:12px;padding-block:7px}
  .live-pill{font-size:.66rem;letter-spacing:.1em;padding:6px 12px 6px 10px}
  .ticker-track span{font-size:.74rem}
}
@media (max-width:420px){
  .ticker{display:none}
  .utility .wrap{justify-content:center}
}

/* ---------- animated call button: hot water filling, steam rising ---------- */
.callbtn{position:relative;display:inline-flex;align-items:center;isolation:isolate;overflow:hidden;
  border-radius:var(--r-pill);padding:0;text-decoration:none;flex:none;min-height:54px;
  background:linear-gradient(180deg,#16254a 0%,#0d1730 100%);
  border:1.5px solid rgba(255,255,255,.22);
  box-shadow:0 10px 26px -12px rgba(0,0,0,.8),inset 0 1px 0 rgba(255,255,255,.14);
  transition:transform var(--t) var(--ease),border-color var(--t) var(--ease),box-shadow var(--t) var(--ease)}
.site-header.is-stuck .callbtn,.site-header.menu-open .callbtn{border-color:rgba(32,56,110,.26)}
.callbtn-liquid{position:absolute;left:0;right:0;bottom:0;height:44%;z-index:0;
  background:linear-gradient(180deg,rgba(214,78,65,.97) 0%,#9c2f26 100%);
  animation:liquid-rise 5.2s var(--ease) infinite}
.callbtn-liquid::before,.callbtn-liquid::after{content:"";position:absolute;left:-52%;right:-52%;top:-7px;height:14px;
  background:radial-gradient(60% 115% at 50% 100%,#cb4236 0 64%,transparent 66%);
  background-size:26px 14px;background-repeat:repeat-x}
.callbtn-liquid::before{animation:wave-a 2.6s linear infinite}
.callbtn-liquid::after{top:-4px;opacity:.6;animation:wave-b 3.8s linear infinite}
@keyframes liquid-rise{0%,100%{height:38%}46%{height:54%}70%{height:46%}}
@keyframes wave-a{from{transform:translateX(0)}to{transform:translateX(26px)}}
@keyframes wave-b{from{transform:translateX(0)}to{transform:translateX(-26px)}}
.callbtn-liquid::marker{content:""}
.callbtn-boil{position:absolute;left:0;right:0;bottom:0;height:46%;z-index:1;pointer-events:none;overflow:hidden}
.callbtn-boil i{position:absolute;bottom:-6px;width:5px;height:5px;border-radius:50%;
  background:radial-gradient(circle at 34% 30%,rgba(255,255,255,.95),rgba(255,214,206,.5) 60%,rgba(255,255,255,0) 72%);
  opacity:0;animation:boil 2.4s linear infinite}
.callbtn-boil i:nth-child(1){left:14%;animation-delay:0s}
.callbtn-boil i:nth-child(2){left:31%;width:4px;height:4px;animation-delay:.5s;animation-duration:2.1s}
.callbtn-boil i:nth-child(3){left:49%;width:6px;height:6px;animation-delay:1s;animation-duration:2.7s}
.callbtn-boil i:nth-child(4){left:66%;width:4px;height:4px;animation-delay:1.5s;animation-duration:2.2s}
.callbtn-boil i:nth-child(5){left:82%;animation-delay:1.9s;animation-duration:2.5s}
@keyframes boil{
  0%{opacity:0;transform:translateY(0) scale(.5)}
  18%{opacity:.95}
  78%{opacity:.7}
  100%{opacity:0;transform:translateY(-32px) scale(1.25)}
}
.callbtn-steam{position:absolute;inset:0;z-index:4;pointer-events:none;overflow:hidden}
.callbtn-steam i{position:absolute;bottom:34%;width:16px;height:16px;border-radius:50%;
  background:radial-gradient(circle,rgba(255,255,255,.8),rgba(255,236,232,.3) 48%,rgba(255,255,255,0) 72%);
  filter:blur(4.5px);opacity:0;animation:steam 4.2s var(--ease) infinite}
.callbtn-steam i:nth-child(1){left:12%;animation-delay:0s}
.callbtn-steam i:nth-child(2){left:38%;width:20px;height:20px;animation-delay:1.4s;animation-duration:4.8s}
.callbtn-steam i:nth-child(3){left:64%;width:18px;height:18px;animation-delay:2.8s;animation-duration:4.4s}
.callbtn-steam i:nth-child(4){left:85%;width:14px;height:14px;animation-delay:2s;animation-duration:5s}
@keyframes steam{
  0%{opacity:0;transform:translateY(10px) scale(.45)}
  28%{opacity:.9}
  65%{opacity:.55;transform:translateY(-10px) scale(1.5) translateX(3px)}
  100%{opacity:0;transform:translateY(-26px) scale(2.3) translateX(-2px)}
}
.callbtn-face{position:relative;z-index:5;display:flex;align-items:center;gap:.7em;padding:8px 20px 8px 9px}
.callbtn-ring{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;flex:none;color:#fff;
  background:rgba(255,255,255,.18);border:1.5px solid rgba(255,255,255,.4);
  animation:ring-shake 4s var(--ease) infinite}
.callbtn-ring .ic{width:17px;height:17px}
@keyframes ring-shake{
  0%,58%,100%{transform:rotate(0)}
  62%{transform:rotate(-16deg)}66%{transform:rotate(14deg)}
  70%{transform:rotate(-11deg)}74%{transform:rotate(9deg)}78%{transform:rotate(0)}
}
.callbtn-txt{display:flex;flex-direction:column;line-height:1.1;font-family:var(--ff-head);font-weight:700;
  font-size:1.03rem;color:#fff;letter-spacing:.01em;white-space:nowrap}
.callbtn-txt small{font-family:var(--ff-body);font-weight:600;font-size:.63rem;letter-spacing:.11em;
  text-transform:uppercase;color:rgba(255,255,255,.72);margin-bottom:3px}
.callbtn:hover{transform:translateY(-2px);border-color:rgba(255,255,255,.55);
  box-shadow:0 16px 34px -12px rgba(203,66,54,.85),inset 0 1px 0 rgba(255,255,255,.2)}
.callbtn:hover .callbtn-liquid{animation-duration:2.2s}
.callbtn:active{transform:translateY(0)}
@media (max-width:1399px){
  .callbtn-txt{font-size:.95rem}
  .callbtn-face{padding:7px 16px 7px 8px}
  .callbtn-ring{width:34px;height:34px}
}

/* ---------- shining headline phrase ---------- */
.shine{position:relative;display:inline-block;
  background:linear-gradient(100deg,#ffffff 0%,#ffffff 36%,#ffd9d3 44%,#ffffff 52%,#ffffff 100%);
  background-size:280% 100%;
  -webkit-background-clip:text;background-clip:text;color:transparent;
  animation:shine-sweep 5.5s var(--ease) infinite}
@keyframes shine-sweep{0%{background-position:160% 0}55%,100%{background-position:-60% 0}}
.shine::after{content:"";position:absolute;left:-6%;right:-6%;bottom:-.1em;height:.1em;border-radius:3px;
  background:linear-gradient(90deg,transparent,var(--red) 22%,#ff8f82 50%,var(--red) 78%,transparent);
  opacity:.9;animation:shine-bar 5.5s var(--ease) infinite}
@keyframes shine-bar{0%,20%{transform:scaleX(0);opacity:0}45%{transform:scaleX(1);opacity:.95}85%,100%{transform:scaleX(1);opacity:.5}}

/* ---------- louder CTAs ---------- */
.btn-primary{position:relative}
.btn-primary::after{content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none;z-index:0;
  background:linear-gradient(115deg,transparent 30%,rgba(255,255,255,.4) 46%,transparent 62%);
  background-size:260% 100%;background-position:170% 0;animation:btn-sheen 4.4s var(--ease) infinite}
@keyframes btn-sheen{0%{background-position:170% 0}48%,100%{background-position:-70% 0}}
.hero-actions .btn-primary{box-shadow:0 14px 30px -10px rgba(203,66,54,.95),0 0 0 0 rgba(203,66,54,.5);
  animation:cta-pulse 3.2s var(--ease) infinite}
@keyframes cta-pulse{
  0%,100%{box-shadow:0 14px 30px -10px rgba(203,66,54,.95),0 0 0 0 rgba(203,66,54,.55)}
  60%{box-shadow:0 14px 30px -10px rgba(203,66,54,.95),0 0 0 14px rgba(203,66,54,0)}
}
.eyebrow{font-weight:700}
.q-mobar-quote{position:relative;overflow:hidden}
.q-mobar-quote::after{content:"";position:absolute;inset:0;pointer-events:none;
  background:linear-gradient(115deg,transparent 32%,rgba(255,255,255,.34) 48%,transparent 64%);
  background-size:260% 100%;animation:btn-sheen 3.6s var(--ease) infinite}

@media (prefers-reduced-motion:reduce){
  .ticker-track,.live-pill,.live-dot::after,.callbtn-liquid,.callbtn-liquid::before,.callbtn-liquid::after,
  .callbtn-steam i,.callbtn-boil i,.callbtn-ring,.shine,.shine::after,.btn-primary::after,.hero-actions .btn-primary,
  .q-mobar-quote::after{animation:none!important}
  .shine{background:none;-webkit-text-fill-color:#fff;color:#fff}
  .shine::after{opacity:.9;transform:none}
}

/* ---------- header fits its new contents ---------- */
@media (max-width:1520px){
  .callbtn-txt small{display:none}
  .callbtn-txt{font-size:1rem}
  .callbtn-face{padding:7px 17px 7px 8px}
  .callbtn{min-height:48px}
  .callbtn-steam{top:-4px;left:12px;width:44px}
}
@media (max-width:1380px){
  .nav-list>li>a,.nav-toggle-sub{padding:11px 7px;font-size:.87rem}
  .nav-list>li>a::after,.nav-toggle-sub::after{left:7px;right:7px}
  .hdr-cta{gap:8px}
  .btn-quote-hdr{padding-left:16px}
}
@media (max-width:1319px){
  .nav-main{display:none}
  .burger{display:inline-flex}
  .hdr-cta .btn-quote-hdr{display:none}
}

/* hero copy sits over a lighter photo on narrow screens, so give it a soft lift */
@media (max-width:1180px){
  .hero h1,.hero-lede,.hero .eyebrow,.hero-note{text-shadow:0 2px 14px rgba(5,9,20,.75)}
}

/* the tab label is one inline run inside the flex box, so its spaces survive */
.q-tab-line{display:inline;white-space:nowrap}
.q-tab-text em{font-style:normal;color:var(--red-300)}

/* ============================================================
   v7: cart in the global header
   ============================================================ */
.cartbtn{position:relative;display:inline-flex;align-items:center;justify-content:center;width:50px;height:50px;
  border:1.5px solid rgba(255,255,255,.34);border-radius:var(--r);background:transparent;cursor:pointer;color:#fff;flex:none;
  transition:background-color var(--t) var(--ease),color var(--t) var(--ease),border-color var(--t) var(--ease),transform var(--t) var(--ease)}
.site-header.is-stuck .cartbtn,.site-header.menu-open .cartbtn{border-color:var(--line-2);color:var(--navy)}
.cartbtn:hover{background:var(--red);border-color:var(--red);color:#fff;transform:translateY(-2px)}
.cartbtn .ic-lg{width:21px;height:21px}
.cart-n{position:absolute;top:-7px;right:-7px;min-width:21px;height:21px;padding:0 5px;border-radius:var(--r-pill);
  background:var(--red);color:#fff;font-family:var(--ff-head);font-weight:700;font-size:.7rem;line-height:21px;
  text-align:center;box-shadow:0 0 0 2px var(--navy-900);animation:cart-pop .32s var(--ease)}
.site-header.is-stuck .cart-n,.site-header.menu-open .cart-n{box-shadow:0 0 0 2px #fff}
.cart-n[hidden]{display:none}
@keyframes cart-pop{0%{transform:scale(.3);opacity:0}60%{transform:scale(1.22)}100%{transform:scale(1);opacity:1}}
@media (max-width:860px){.cartbtn{width:44px;height:44px;border-radius:var(--r-sm)}.cartbtn .ic-lg{width:19px;height:19px}}

/* ---------- cart drawer ---------- */
#global-cart{position:fixed;top:0;right:0;height:100%;width:min(452px,100%);background:#fff;z-index:96;display:none;
  flex-direction:column;box-shadow:-28px 0 70px -24px rgba(8,13,26,.7);border:0;padding:0;margin:0;max-width:100%;
  max-height:100%;overflow:hidden}
#global-cart.open{display:flex}
.cart-body{flex:1;overflow-y:auto;padding:0}
.cart-empty{display:flex;flex-direction:column;align-items:center;text-align:center;gap:14px;
  padding:clamp(34px,7vw,56px) clamp(22px,5.5%,34px)}
.cart-empty[hidden]{display:none}
.cart-empty-ic{width:72px;height:72px;border-radius:50%;background:var(--navy-50);display:grid;place-items:center;margin-bottom:2px}
.cart-empty-ic svg{width:30px;height:30px;fill:var(--navy)}
.cart-empty h3{margin:0;font-size:1.2rem}
.cart-empty p{margin:0;font-size:.93rem;max-width:34ch;color:var(--body)}
.cart-empty .btn{width:100%;max-width:300px}
.cart-empty .btn-ghost{min-height:48px}
.cart-list{list-style:none;margin:0;padding:clamp(18px,4%,24px) clamp(22px,5.5%,34px)}
.cart-list[hidden]{display:none}
.cart-list>li{display:grid;grid-template-columns:72px 1fr auto;gap:14px;margin:0;padding:16px 0;
  border-bottom:1px solid var(--line);align-items:start}
.cart-list>li:first-child{padding-top:0}
.cart-list>li:last-child{border-bottom:0;padding-bottom:0}
.cart-thumb{width:72px;height:72px;border-radius:var(--r);background:var(--paper-2);overflow:hidden;display:grid;place-items:center}
.cart-thumb img{width:100%;height:100%;object-fit:contain;padding:6px}
.cart-thumb svg{width:24px;height:24px;fill:var(--navy-300)}
.cart-info{min-width:0}
.cart-info h4{margin:0 0 4px;font-family:var(--ff-head);font-weight:600;font-size:.97rem;line-height:1.35;color:var(--ink)}
.cart-info a{color:inherit;text-decoration:none}
.cart-info a:hover{color:var(--red-700)}
.cart-meta{margin:0;font-size:.82rem;color:var(--muted)}
.cart-qty{display:inline-flex;align-items:center;gap:2px;margin-top:9px;border:1px solid var(--line-2);border-radius:var(--r-sm);overflow:hidden}
.cart-qty button{width:30px;height:30px;border:0;background:#fff;color:var(--navy);cursor:pointer;font-family:var(--ff-head);
  font-weight:700;font-size:1rem;line-height:1;transition:background-color var(--t) var(--ease)}
.cart-qty button:hover{background:var(--navy-50)}
.cart-qty span{min-width:30px;text-align:center;font-family:var(--ff-head);font-weight:600;font-size:.9rem;color:var(--ink)}
.cart-right{display:flex;flex-direction:column;align-items:flex-end;gap:10px}
.cart-price{font-family:var(--ff-head);font-weight:700;font-size:1rem;color:var(--ink);white-space:nowrap}
.cart-del{border:0;background:none;cursor:pointer;color:var(--muted);padding:4px;border-radius:var(--r-xs);
  transition:color var(--t) var(--ease)}
.cart-del svg{width:15px;height:15px;fill:currentColor}
.cart-del:hover{color:var(--red-700)}
.cart-foot{border-top:1px solid var(--line);padding:clamp(18px,4%,22px) clamp(22px,5.5%,34px) clamp(22px,5%,28px);
  background:var(--paper-2)}
.cart-foot[hidden]{display:none}
.cart-sub-row{display:flex;align-items:baseline;justify-content:space-between;gap:16px;margin:0 0 4px;
  font-family:var(--ff-head);font-weight:600;font-size:1rem;color:var(--ink)}
.cart-sub-row strong{font-size:1.3rem;font-weight:700}
.cart-note{margin:0 0 16px;font-size:.8rem;color:var(--muted)}
.cart-actions{display:grid;grid-template-columns:1fr 1.25fr;gap:10px}
.cart-actions .btn{width:100%;min-height:52px}
@media (max-width:420px){.cart-actions{grid-template-columns:1fr}}
@media (prefers-reduced-motion:reduce){.cart-n{animation:none}.cartbtn:hover{transform:none}}

/* ---------- dropdowns open on hover, with a bridge across the gap ---------- */
.nav-list li{position:relative}
.subnav::before{content:"";position:absolute;left:0;right:0;top:-14px;height:14px}
@media (hover:hover) and (pointer:fine){
  .nav-list>li:hover>.subnav{display:block}
}

/* ============================================================
   CSS-only state. Base44 can strip page scripts on import, so the
   drawers, the side quote tab, the cart and the mobile menu are
   driven by hidden checkboxes and <label for> instead of JS.
   The site-wide script, when added, layers on top of this.
   ============================================================ */
.shws-state{position:fixed;top:0;left:0;width:1px;height:1px;opacity:0;pointer-events:none;margin:0;padding:0;border:0;clip-path:inset(50%)}
.site-header label[role="button"]{user-select:none;-webkit-user-select:none}
.q-tab,.q-mobar-quote,.cartbtn,.burger,.q-close,.btn-quote-hdr{cursor:pointer}

/* mobile menu */
#shws-menu:checked ~ .mobile-panel{display:block}
.site-header:has(#shws-menu:checked)::after{opacity:1}
.site-header:has(#shws-menu:checked) .hdr::after{opacity:0}
.site-header:has(#shws-menu:checked) .brand img{background:transparent;padding:0}
.site-header:has(#shws-menu:checked) .nav-list>li>a,
.site-header:has(#shws-menu:checked) .nav-toggle-sub{color:var(--ink)}
.site-header:has(#shws-menu:checked) .burger,
.site-header:has(#shws-menu:checked) .call-icon{border-color:var(--line-2);color:var(--navy)}
.site-header:has(#shws-menu:checked) .callbtn{border-color:rgba(32,56,110,.26)}
.site-header:has(#shws-menu:checked) .cartbtn{border-color:var(--line-2);color:var(--navy)}
.site-header:has(#shws-menu:checked) .cart-n{box-shadow:0 0 0 2px #fff}

/* quote drawer */
#shws-quote:checked ~ #global-quick-quote{display:flex}
#shws-quote:checked ~ .q-backdrop-quote{display:block}
/* cart drawer */
#shws-cart:checked ~ #global-cart{display:flex}
#shws-cart:checked ~ .q-backdrop-cart{display:block}
/* one drawer at a time: the quote drawer wins */
#shws-quote:checked ~ #global-cart,
#shws-quote:checked ~ .q-backdrop-cart{display:none}
/* lock the page behind an open drawer */
html:has(#shws-quote:checked),html:has(#shws-cart:checked){overflow:hidden}

/* A page with a dark full-bleed hero keeps the original transparent header
   with white type. Every other page gets dark type so the nav stays readable.
   :has() reaches across Base44's parts, so this needs no JavaScript. */
body:not(:has(.hero)) .site-header .hdr::after{background:rgba(32,56,110,.13)}
body:not(:has(.hero)) .site-header .brand img{background:transparent;padding:0}
body:not(:has(.hero)) .site-header .nav-list>li>a,
body:not(:has(.hero)) .site-header .nav-toggle-sub{color:var(--ink)}
body:not(:has(.hero)) .site-header .nav-list>li>a:hover,
body:not(:has(.hero)) .site-header .nav-toggle-sub:hover,
body:not(:has(.hero)) .site-header .nav-toggle-sub[aria-expanded="true"]{color:var(--navy)}
body:not(:has(.hero)) .site-header .burger,
body:not(:has(.hero)) .site-header .call-icon{border-color:var(--line-2);color:var(--navy)}
body:not(:has(.hero)) .site-header .burger:hover,
body:not(:has(.hero)) .site-header .call-icon:hover{border-color:var(--red);color:#fff}
body:not(:has(.hero)) .site-header .callbtn{border-color:rgba(32,56,110,.26)}
body:not(:has(.hero)) .site-header .cartbtn{border-color:var(--line-2);color:var(--navy)}
body:not(:has(.hero)) .site-header .cartbtn:hover{border-color:var(--red);color:#fff}
body:not(:has(.hero)) .site-header .cart-n{box-shadow:0 0 0 2px #fff}

/* On a page with a dark hero the header starts transparent with white type and
   turns solid white on scroll. The script does that by adding .is-stuck; where
   the browser supports scroll-driven animations it also happens with no script
   at all, so the header never sits as white type over white content. The menu
   guard keeps the open mobile panel on its own white backdrop. */
@supports (animation-timeline: scroll()) {
  @keyframes shws-stick-panel{from{opacity:0}to{opacity:1}}
  @keyframes shws-stick-hairline{from{opacity:1}to{opacity:0}}
  @keyframes shws-stick-logo{from{background-color:#fff;padding:7px 10px}to{background-color:transparent;padding:0}}
  @keyframes shws-stick-ink{from{color:#fff}to{color:var(--ink)}}
  @keyframes shws-stick-icon{from{border-color:rgba(255,255,255,.4);color:#fff}to{border-color:var(--line-2);color:var(--navy)}}
  @keyframes shws-stick-cart{from{border-color:rgba(255,255,255,.34);color:#fff}to{border-color:var(--line-2);color:var(--navy)}}
  @keyframes shws-stick-call{from{border-color:rgba(255,255,255,.22)}to{border-color:rgba(32,56,110,.26)}}
  @keyframes shws-stick-ring{from{box-shadow:0 0 0 2px var(--navy-900)}to{box-shadow:0 0 0 2px #fff}}

  body:has(.hero) .site-header:not(:has(#shws-menu:checked))::after,
  body:has(.hero) .site-header:not(:has(#shws-menu:checked)) .hdr::after,
  body:has(.hero) .site-header:not(:has(#shws-menu:checked)) .brand img,
  body:has(.hero) .site-header:not(:has(#shws-menu:checked)) .nav-list>li>a,
  body:has(.hero) .site-header:not(:has(#shws-menu:checked)) .nav-toggle-sub,
  body:has(.hero) .site-header:not(:has(#shws-menu:checked)) .burger,
  body:has(.hero) .site-header:not(:has(#shws-menu:checked)) .call-icon,
  body:has(.hero) .site-header:not(:has(#shws-menu:checked)) .cartbtn,
  body:has(.hero) .site-header:not(:has(#shws-menu:checked)) .cart-n,
  body:has(.hero) .site-header:not(:has(#shws-menu:checked)) .callbtn{
    animation-duration:auto;animation-fill-mode:both;animation-timing-function:steps(1,end);
    animation-timeline:scroll(root block);animation-range:0 14px}

  body:has(.hero) .site-header:not(:has(#shws-menu:checked))::after{animation-name:shws-stick-panel}
  body:has(.hero) .site-header:not(:has(#shws-menu:checked)) .hdr::after{animation-name:shws-stick-hairline}
  body:has(.hero) .site-header:not(:has(#shws-menu:checked)) .brand img{animation-name:shws-stick-logo}
  body:has(.hero) .site-header:not(:has(#shws-menu:checked)) .nav-list>li>a,
  body:has(.hero) .site-header:not(:has(#shws-menu:checked)) .nav-toggle-sub{animation-name:shws-stick-ink}
  body:has(.hero) .site-header:not(:has(#shws-menu:checked)) .burger,
  body:has(.hero) .site-header:not(:has(#shws-menu:checked)) .call-icon{animation-name:shws-stick-icon}
  body:has(.hero) .site-header:not(:has(#shws-menu:checked)) .cartbtn{animation-name:shws-stick-cart}
  body:has(.hero) .site-header:not(:has(#shws-menu:checked)) .cart-n{animation-name:shws-stick-ring}
  body:has(.hero) .site-header:not(:has(#shws-menu:checked)) .callbtn{animation-name:shws-stick-call}
}

/* a <label> standing in for a <button> inherits the page's text styles instead
   of the browser's button defaults, so re-assert the few that mattered */
.cartbtn,.burger,.call-icon,.q-tab,.bs-badge,.q-mobar label,.btn{text-align:center}
.cartbtn,.burger,.call-icon{padding:0}

/* ============================================================
   Base44 part wrappers.
   Base44 wraps each imported part in its own div. The header's wrapper is an
   opaque white box, positioned, z-index 1000, and only as tall as the header
   itself. That hides the hero that is meant to sit behind the header, and it
   confines position:sticky so the header scrolls away. So the wrapper carries
   the sticky behaviour instead, and lets the page show through.
   These rules do nothing when the file is opened on its own.
   ============================================================ */
body>[class*="nifty-part-header"]{background:transparent;position:sticky;top:-54px;z-index:1000}
body>[class*="nifty-part-header"] .site-header{position:relative;top:auto}
@media (max-width:860px){body>[class*="nifty-part-header"]{top:-46px}}
/* the product image overlay lives in the page part, so the header part has to
   stand down while it is open or it punches through the overlay */
html:has(#pdp-zoom:checked) body>[class*="nifty-part-header"]{z-index:auto}

/* ---- chrome shared by every page: breadcrumbs, the trust list and the
        inline link button. These live here rather than in a page file so
        every page that uses them is styled. ---- */
.crumbs{background:var(--navy-900);color:var(--d-muted);font-size:.84rem;padding-block:11px}
.crumbs ol{display:flex;flex-wrap:wrap;gap:.5em;list-style:none;margin:0;padding:0}
.crumbs li{margin:0;display:flex;align-items:center;gap:.5em}
.crumbs li+li::before{content:"";width:5px;height:5px;border-radius:50%;background:var(--red);flex:none}
.crumbs a{color:var(--d-body);text-decoration:none}
.crumbs a:hover{color:#fff;text-decoration:underline}
.crumbs [aria-current]{color:#fff;font-weight:600}
.buy-trust{list-style:none;margin:0 0 14px;padding:14px 0 0;border-top:1px solid #dbe3f1;display:grid;gap:9px}
.buy-trust li{margin:0;display:grid;grid-template-columns:20px 1fr;gap:10px;align-items:center;font-size:.86rem;color:var(--body)}
.buy-trust .ic{width:20px;height:20px;padding:5px;border-radius:50%;background:var(--red);color:#fff;box-sizing:border-box}
.linkish{border:0;background:none;padding:0;font:inherit;color:var(--navy);font-weight:700;cursor:pointer;text-decoration:underline;text-underline-offset:3px}
.linkish:hover{color:var(--red-700)}

/* the options the customer chose, listed inside the cart drawer */
.cart-opts{list-style:none;margin:8px 0 0;padding:0 0 0 12px;display:grid;gap:3px;border-left:2px solid var(--line-2)}
.cart-opts li{display:block;margin:0;font-size:.8rem;line-height:1.5;color:var(--body)}

/* accordions open without JavaScript too */
.faq-t:checked ~ .faq-a{display:block}
.faq-t:checked ~ h3 .faq-q .ic{transform:rotate(45deg);background:var(--red)}
.faq-q{cursor:pointer;user-select:none;-webkit-user-select:none}

/* the floating launcher and back-to-top are JS-gated in the original;
   without the script the launcher simply stays available. */
.q-dock{opacity:1}




:root{
  --navy:#20386e; --navy-900:#0d1426; --navy-800:#121c33; --navy-700:#1a2b55;
  --navy-600:#2b4a8c; --navy-400:#5f7cb8; --navy-300:#93a8d2; --navy-50:#eef2f9;
  --red:#cb4236; --red-700:#a3332a; --red-600:#b93a2f; --red-300:#e8776c; --red-50:#fdefed;
  --ink:#101728; --body:#5f6877; --muted:#7a8496;
  --line:#e5e9f1; --line-2:#ccd4e2; --line-dark:rgba(255,255,255,.14);
  --paper:#ffffff; --paper-2:#f5f7fb; --paper-3:#eef2f8;
  --d-ink:#ffffff; --d-body:#c4d0e6; --d-muted:#8e9cba;
  --r-xs:6px; --r-sm:10px; --r:16px; --r-card:22px; --r-lg:32px; --r-xl:46px; --r-pill:999px;
  --sh-1:0 2px 4px rgba(13,20,38,.04);
  --sh-2:0 18px 44px -20px rgba(13,20,38,.3);
  --sh-3:0 40px 90px -34px rgba(13,20,38,.5);
  --gut:clamp(18px,4.4vw,52px);
  --band:clamp(62px,8vw,124px);
  --band-sm:clamp(46px,5.4vw,84px);
  --maxw:1320px;
  --ff-head:"Jost","Jost Fallback","Segoe UI",system-ui,-apple-system,Arial,sans-serif;
  --ff-body:"Montserrat","Montserrat Fallback","Segoe UI",system-ui,-apple-system,Arial,sans-serif;
  --t:.24s; --t-slow:.55s; --ease:cubic-bezier(.4,.16,.2,1);
}
.wrap{width:100%;max-width:var(--maxw);margin-inline:auto;padding-inline:var(--gut)}
.sprite{display:none}
.site-footer .ic{width:18px;height:18px;fill:currentColor}
.site-footer .socials .ic{width:19px;height:19px}
/* ---------- footer ---------- */
.site-footer{position:relative;background:#070c18;color:var(--d-body);font-size:.94rem;overflow:hidden}
.site-footer>*{position:relative;z-index:1}
.site-footer h3{font-family:var(--ff-head);font-size:.8rem;letter-spacing:.17em;text-transform:uppercase;color:#fff;margin:0 0 18px;font-weight:600}
.site-footer h3.after-grid{margin-top:30px}
.site-footer ul{list-style:none;margin:0;padding:0}
.site-footer li{margin-bottom:0}
.site-footer a{color:var(--d-body);text-decoration:none;display:inline-block;min-height:34px;padding-block:6px;line-height:1.5;transition:color var(--t) var(--ease)}
.site-footer a:hover{color:#fff;text-decoration:underline}
.f-grid{display:grid;grid-template-columns:1.6fr 1fr 1fr 1.25fr;gap:clamp(28px,3vw,56px);padding-block:clamp(52px,6vw,88px) clamp(40px,4.4vw,64px);align-items:start}
.f-brand img{width:182px;margin-bottom:22px;background:#fff;padding:11px 14px;border-radius:var(--r)}
.f-brand p{max-width:40ch;color:var(--d-muted)}
.site-footer .f-contact{background:rgba(255,255,255,.055);border:1px solid var(--line-dark);border-radius:var(--r-card);padding:18px 20px}
.f-contact li{display:flex;gap:.7em;align-items:flex-start;min-height:34px}
.f-contact li+li{margin-top:6px}
.f-contact span{padding-block:6px;min-width:0}
.f-contact a,.f-contact span{overflow-wrap:anywhere}
.f-contact .ic{color:#fff;background:var(--red);border-radius:50%;padding:6px;width:26px;height:26px;box-sizing:border-box;margin-top:7px;flex:none}
.f-brands{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));column-gap:14px}
.socials{display:flex;flex-wrap:wrap;gap:10px;margin-top:24px}
.socials a{width:44px;height:44px;border-radius:50%;background:rgba(255,255,255,.09);display:grid;place-items:center;color:#fff;min-height:0;padding:0;transition:background-color var(--t) var(--ease),transform var(--t) var(--ease)}
.socials a:hover{background:var(--red);transform:translateY(-3px)}
