.nifty-part-header-1 .eyebrow::before {content:"";width:22px;height:22px;flex:none;border-radius:50%;background:var(--red);
  -webkit-mask:radial-gradient(circle at 50% 50%,transparent 0 3.6px,#000 3.6px);
