.btn-primary:active{transform:translateY(0)}
.btn-navy{background:var(--navy);color:#fff;border-color:var(--navy)}
.btn-navy .bdg{background:#fff;color:var(--navy)}
.btn-navy:hover{background:var(--navy-700);border-color:var(--navy-700);color:#fff;transform:translateY(-2px)}
.btn-ghost{background:transparent;color:var(--navy);border-color:var(--line-2)}
.btn-ghost .bdg{background:var(--navy-50);color:var(--navy)}
.btn-ghost:hover{border-color:var(--navy);background:var(--navy-50);color:var(--navy)}
.btn-onDark{background:transparent;color:#fff;border-color:rgba(255,255,255,.42)}
.btn-onDark .bdg{background:rgba(255,255,255,.16);color:#fff}
.btn-onDark:hover{background:#fff;color:var(--navy-900);border-color:#fff;transform:translateY(-2px)}
.btn-onDark:hover .bdg{background:var(--navy-900);color:#fff}
.btn-sm{padding:10px 16px 10px 20px;font-size:.88rem;min-height:46px;gap:.5em}
.btn-sm .bdg{width:26px;height:26px}
.btn-sm .bdg svg{width:11px;height:11px}

/* ---------- utility bar ---------- */
.utility{background:var(--navy-900);color:var(--d-body);font-size:.84rem;position:relative;z-index:3}

/* ---------- header ---------- */
.site-header{position:sticky;top:-54px;z-index:60;background:transparent}
.site-header::after{content:"";position:absolute;left:0;right:0;top:0;bottom:0;background:#fff;box-shadow:0 10px 34px -20px rgba(13,20,38,.6);opacity:0;transition:opacity var(--t) var(--ease);pointer-events:none;z-index:-1}
.site-header.is-stuck::after,.site-header.menu-open::after{opacity:1}
.hdr{display:flex;align-items:center;gap:18px;justify-content:space-between;padding-block:15px;position:relative}
.hdr::after{content:"";position:absolute;left:var(--gut);right:var(--gut);bottom:0;height:1px;background:rgba(255,255,255,.16);transition:opacity var(--t) var(--ease)}
.site-header.is-stuck .hdr::after,.site-header.menu-open .hdr::after{opacity:0}
.hdr>*{min-width:0}
.brand{display:inline-flex;align-items:center;flex:none;min-width:0}
.brand img{width:184px;max-width:46vw;background:#fff;padding:7px 10px;border-radius:var(--r-sm);transition:background-color var(--t) var(--ease),padding var(--t) var(--ease)}
.site-header.is-stuck .brand img,.site-header.menu-open .brand img{background:transparent;padding:0}
.nav-main{margin-left:auto;flex:0 0 auto}
.nav-list{display:flex;align-items:center;gap:2px;margin:0;padding:0;list-style:none;flex-wrap:nowrap}
.nav-list li{margin:0;position:relative}
.nav-list>li>a,.nav-toggle-sub{position:relative;display:inline-flex;align-items:center;gap:.34em;white-space:nowrap;font-family:var(--ff-head);font-weight:500;font-size:.96rem;color:#fff;text-decoration:none;padding:11px 12px;border-radius:var(--r-xs);background:none;border:0;cursor:pointer;transition:color var(--t) var(--ease)}
.site-header.is-stuck .nav-list>li>a,.site-header.is-stuck .nav-toggle-sub,.site-header.menu-open .nav-list>li>a{color:var(--ink)}
.nav-list>li>a::after,.nav-toggle-sub::after{content:"";position:absolute;left:12px;right:12px;bottom:4px;height:2px;border-radius:2px;background:var(--red);transform:scaleX(0);transform-origin:left;transition:transform var(--t) var(--ease)}
.nav-list>li>a:hover,.nav-toggle-sub:hover,.nav-toggle-sub[aria-expanded="true"]{color:#fff}
.site-header.is-stuck .nav-list>li>a:hover,.site-header.is-stuck .nav-toggle-sub:hover,.site-header.is-stuck .nav-toggle-sub[aria-expanded="true"]{color:var(--navy)}
.nav-list>li>a:hover::after,.nav-toggle-sub:hover::after,.nav-toggle-sub[aria-expanded="true"]::after{transform:scaleX(1)}
.nav-toggle-sub .ic{transition:transform var(--t) var(--ease)}
.nav-toggle-sub[aria-expanded="true"] .ic{transform:rotate(180deg)}
.subnav{position:absolute;top:calc(100% + 12px);left:0;min-width:306px;background:#fff;border:1px solid var(--line);border-radius:var(--r-card);box-shadow:var(--sh-3);padding:10px;margin:0;list-style:none;display:none;z-index:70}
.subnav.open{display:block}
.subnav a{display:block;padding:11px 15px;border-radius:var(--r);font-size:.94rem;color:var(--ink);text-decoration:none;font-weight:600;font-family:var(--ff-head);transition:background-color var(--t) var(--ease),color var(--t) var(--ease)}
.subnav a span{display:block;font-family:var(--ff-body);font-weight:400;font-size:.8rem;color:var(--muted);margin-top:2px;line-height:1.45}
.subnav a:hover{background:var(--navy-50);color:var(--navy)}
.subnav a:hover span{color:var(--body)}
.hdr-cta{display:flex;align-items:center;gap:10px;flex:none}
.hdr-cta .btn{white-space:nowrap}
.burger,.call-icon{display:none;align-items:center;justify-content:center;width:50px;height:50px;border:1.5px solid rgba(255,255,255,.4);border-radius:var(--r);background:transparent;cursor:pointer;color:#fff;transition:background-color var(--t) var(--ease),color var(--t) var(--ease),border-color var(--t) var(--ease)}
.site-header.is-stuck .burger,.site-header.is-stuck .call-icon,.site-header.menu-open .burger,.site-header.menu-open .call-icon{border-color:var(--line-2);color:var(--navy)}
.burger:hover,.call-icon:hover{background:var(--red);color:#fff;border-color:var(--red)}
.mobile-panel{display:none;background:#fff;max-height:70vh;overflow-y:auto;border-radius:0 0 var(--r-lg) var(--r-lg);box-shadow:var(--sh-3);position:relative;z-index:2}
.mobile-panel.open{display:block}
.mobile-panel ul{list-style:none;margin:0;padding:6px 0 22px}
.mobile-panel li{margin:0}
.mobile-panel a{display:block;padding:13px var(--gut);font-family:var(--ff-head);font-weight:600;color:var(--ink);text-decoration:none;border-bottom:1px solid var(--line)}
.mobile-panel a.sub{padding-left:calc(var(--gut) + 20px);font-weight:400;font-family:var(--ff-body);color:var(--body);font-size:.95rem}
.mobile-panel a:hover{background:var(--navy-50);color:var(--navy)}
.mobile-actions{display:flex;gap:10px;padding:18px var(--gut) 8px;flex-wrap:wrap}
.mobile-actions .btn{flex:1 1 170px}
@media (max-width:1399px){.nav-list>li>a,.nav-toggle-sub{padding:11px 8px;font-size:.9rem}.nav-list>li>a::after,.nav-toggle-sub::after{left:8px;right:8px}}
/* the utility strip scrolls away; only the main bar stays pinned */
@media (max-width:860px){.site-header{top:-46px}}
@media (max-width:1279px){.nav-main{display:none}.burger{display:inline-flex}.hdr-cta .btn-quote-hdr{display:none}}
@media (max-width:640px){.hdr{gap:10px}.brand img{width:150px}.hdr-cta .btn-call-hdr{display:none}.call-icon{display:inline-flex}}

/* ---------- hero: full-bleed media, overlay, display type ---------- */
.hero{position:relative;background:var(--navy-900);color:var(--d-body);--hdr-bar:111px;margin-top:calc(var(--hdr-bar) * -1);padding-top:var(--hdr-bar);isolation:isolate}
.hero .media{position:absolute;inset:0;z-index:0;margin:0}
.hero .fig{margin:0;border-radius:0;height:100%;background:var(--navy-800);box-shadow:none}
.hero .fig picture{display:block;height:100%}
.hero .fig img{width:100%;height:100%;aspect-ratio:auto;object-fit:cover;object-position:56% 50%;filter:brightness(1.08) saturate(1.06) contrast(1.03)}
.hero .media::after{content:"";position:absolute;inset:0;z-index:1;pointer-events:none;background:
  linear-gradient(94deg,rgba(10,16,30,.95) 0%,rgba(10,16,30,.88) 36%,rgba(10,16,30,.6) 62%,rgba(10,16,30,.5) 100%),
  linear-gradient(180deg,rgba(10,16,30,.8) 0%,transparent 28%,rgba(10,16,30,.55) 100%)}
.hero .fig figcaption{position:absolute;z-index:2;right:var(--gut);bottom:clamp(104px,11vw,150px);width:min(380px,calc(100% - var(--gut)*2));
  font-family:var(--ff-body);font-size:.73rem;line-height:1.55;padding:14px 17px;border-radius:var(--r);
  background:rgba(10,16,30,.76);color:#cfd9ec;border:1px solid rgba(255,255,255,.17);backdrop-filter:blur(6px)}
.hero .fig figcaption b{color:#fff;font-family:var(--ff-head);font-weight:600;display:block;font-size:.72rem;letter-spacing:.13em;text-transform:uppercase;margin-bottom:4px}
.hero .fig figcaption em{display:block;font-style:normal;color:#aab8d4;margin-top:6px}
.hero .wrap{position:static}
.hero-grid>div:first-child{position:relative;z-index:2}
.hero-grid{display:grid;grid-template-columns:minmax(0,1.08fr) minmax(0,352px);gap:clamp(28px,4vw,56px);align-items:center;padding-block:clamp(40px,4.4vw,66px) clamp(96px,9vw,128px);min-height:min(48vh,430px)}
.hero h1{color:#fff;margin-bottom:.46em;max-width:24ch}
.hero .eyebrow{color:#fff}
.hero .eyebrow::before{background:var(--red);box-shadow:inset 0 0 0 99px var(--red)}
.hero-lede{color:#d2dcf0;font-size:clamp(1.02rem,1.3vw,1.17rem);max-width:52ch}
.hero-actions{display:flex;flex-wrap:wrap;gap:13px;margin:32px 0 24px}
.hero-note{display:inline-flex;align-items:center;gap:.6em;font-size:.93rem;color:#dbe4f4;margin:0;font-weight:500}
.hero-note .ic{width:22px;height:22px;padding:5px;border-radius:50%;background:var(--red);color:#fff;box-sizing:border-box}

/* proof strip: white panel riding the hero edge */
.proof{position:relative;z-index:4;display:grid;grid-template-columns:repeat(4,1fr);list-style:none;margin:0 0 calc(var(--panel-drop) * -1);padding:0;background:#fff;border-radius:var(--r-lg);box-shadow:var(--sh-3);overflow:hidden;--panel-drop:clamp(38px,5vw,64px);transform:translateY(var(--panel-drop))}
.proof li{margin:0;padding:clamp(22px,2.4vw,32px) clamp(16px,2vw,30px);display:flex;gap:.8em;align-items:flex-start;font-size:.87rem;line-height:1.5;color:var(--body);border-left:1px solid var(--line)}
.proof li:first-child{border-left:0}
.proof .ic-md{color:#fff;background:var(--navy);border-radius:50%;padding:7px;width:34px;height:34px;box-sizing:border-box;margin-top:1px}
.proof li:nth-child(2) .ic-md,.proof li:nth-child(4) .ic-md{background:var(--red)}
.proof b{display:block;font-family:var(--ff-head);font-size:1.06rem;font-weight:600;color:var(--ink);margin-bottom:2px;letter-spacing:0}
.after-hero{padding-top:calc(var(--band) + clamp(38px,5vw,64px))}

/* ---------- bands ---------- */
.b-wash{background:var(--paper-2)}
.b-tint{background:var(--navy-50)}
.b-enquire{position:relative;overflow:hidden;background:linear-gradient(176deg,#ffffff 0%,#eef2f9 46%,#e4eaf5 100%)}
.b-enquire::after{content:"";position:absolute;inset:0;pointer-events:none;
  background:radial-gradient(52% 60% at 100% 0%,rgba(203,66,54,.09),transparent 62%),
             radial-gradient(48% 56% at 0% 100%,rgba(32,56,110,.09),transparent 64%)}
.b-enquire>*{position:relative;z-index:1}
.b-enquire .form-card{box-shadow:0 40px 90px -34px rgba(13,20,38,.42)}
.b-navy{background:var(--navy-900);color:var(--d-body);position:relative;overflow:hidden}
.b-navy{background:linear-gradient(168deg,#16213c 0%,#0d1426 62%,#0b1120 100%)}
.b-navy::after{content:"";position:absolute;inset:0;pointer-events:none;background:radial-gradient(70% 86% at 86% 4%,rgba(43,74,140,.42),transparent 64%)}
.b-navy>*{position:relative;z-index:1}
.b-navy h2,.b-navy h3{color:#fff}
.b-navy .lede,.b-navy p{color:var(--d-body)}
.b-navy .eyebrow{color:#fff}
.b-round{border-radius:var(--r-xl) var(--r-xl) 0 0}
.b-round-b{border-radius:0 0 var(--r-xl) var(--r-xl)}

/* ---------- service panels ---------- */
.svc-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:clamp(16px,1.7vw,24px)}
.svc{position:relative;display:flex;flex-direction:column;background:#fff;border:1px solid var(--line);border-radius:var(--r-card);padding:clamp(26px,2.6vw,38px);text-decoration:none;overflow:hidden;transition:border-color var(--t) var(--ease),box-shadow var(--t) var(--ease),transform var(--t) var(--ease)}
.svc::before{content:"";position:absolute;inset:auto auto 0 0;width:100%;height:4px;background:var(--red);transform:scaleX(0);transform-origin:left;transition:transform var(--t-slow) var(--ease)}
.svc:hover{border-color:transparent;box-shadow:var(--sh-2);transform:translateY(-4px)}
.svc:hover::before{transform:scaleX(1)}
.svc .badge{width:62px;height:62px;border-radius:var(--r);background:var(--navy-50);color:var(--navy);display:grid;place-items:center;margin-bottom:22px;transition:background-color var(--t) var(--ease),color var(--t) var(--ease)}
.svc .badge svg{width:28px;height:28px}
.svc:hover .badge{background:var(--red);color:#fff}
.svc h3{margin-bottom:.45em;font-size:clamp(1.12rem,1.5vw,1.32rem)}
.svc p{font-size:.96rem;color:var(--body);margin-bottom:1.2em}
.svc .more{margin-top:auto;font-family:var(--ff-head);font-weight:600;font-size:.93rem;color:var(--navy);display:inline-flex;align-items:center;gap:.5em}
.svc .more .ic{width:28px;height:28px;padding:8px;border-radius:50%;background:var(--navy-50);color:var(--navy);box-sizing:border-box;transition:transform var(--t) var(--ease),background-color var(--t) var(--ease),color var(--t) var(--ease)}
.svc:hover .more{color:var(--red-700)}
.svc:hover .more .ic{background:var(--red);color:#fff;transform:rotate(-45deg)}

/* ---------- split ---------- */
.split{display:grid;grid-template-columns:minmax(0,1.02fr) minmax(0,.98fr);gap:clamp(32px,4.6vw,78px);align-items:center}
.split-copy>p:last-of-type{margin-bottom:1.6em}
.media{position:relative}
.fig{position:relative;z-index:1;margin:0;border-radius:var(--r-lg);overflow:hidden;background:var(--navy-800);box-shadow:var(--sh-3)}
.fig img{width:100%;aspect-ratio:16/11;object-fit:cover}
.fig.sq img{aspect-ratio:1/1}
.fig.wide img{aspect-ratio:16/9}
.fig figcaption{font-family:var(--ff-body);font-size:.74rem;line-height:1.55;padding:13px 17px;background:var(--paper-3);color:#5b657a;border-top:1px solid var(--line)}
.fig figcaption b{color:var(--navy);font-family:var(--ff-head);font-weight:600;display:block;font-size:.73rem;letter-spacing:.11em;text-transform:uppercase;margin-bottom:3px}
.fig figcaption em{display:block;font-style:normal;color:var(--body);margin-top:5px}
@media (min-width:1040px){
  .hero .media::before{content:none}
  .media::before{content:"";position:absolute;z-index:0;top:26px;left:26px;right:-26px;bottom:-26px;border:1.5px solid rgba(203,66,54,.42);border-radius:var(--r-lg)}
  .media.flip::before{left:-26px;right:26px}
}

/* ---------- system type cards ---------- */
.types{display:grid;grid-template-columns:repeat(4,1fr);gap:clamp(16px,1.7vw,24px)}
.type{display:flex;flex-direction:column;background:#fff;border:1px solid var(--line);border-radius:var(--r-card);overflow:hidden;text-decoration:none;transition:border-color var(--t) var(--ease),box-shadow var(--t) var(--ease),transform var(--t) var(--ease)}
.type:hover{border-color:transparent;box-shadow:var(--sh-2);transform:translateY(-4px)}
.type-body{padding:clamp(22px,2vw,28px) clamp(20px,1.9vw,26px) 24px;display:flex;flex-direction:column;flex:1;order:1}
.type h3{font-size:1.14rem;margin-bottom:.45em}
.type p{font-size:.92rem;margin-bottom:1.1em;color:var(--body)}
.type .more{margin-top:auto;padding-top:4px;font-family:var(--ff-head);font-weight:600;font-size:.89rem;color:var(--navy);display:inline-flex;align-items:center;gap:.45em}
.type .more .ic{transition:transform var(--t) var(--ease)}
.type:hover .more{color:var(--red-700)}
.type:hover .more .ic{transform:translateX(4px)}
.type-media{position:relative;overflow:hidden;order:2;margin:0 clamp(12px,1.2vw,16px) clamp(12px,1.2vw,16px);border-radius:var(--r);background:linear-gradient(180deg,#f7f9fc 0%,#e9eef6 100%)}
.type-media img{width:100%;aspect-ratio:4/3;object-fit:contain;padding:14px 10px;transition:transform var(--t-slow) var(--ease)}
.type:hover .type-media img{transform:scale(1.05)}
.type-cap{display:block;order:3;margin-top:auto;font-size:.71rem;line-height:1.5;padding:13px clamp(20px,1.9vw,26px) 18px;color:#6b7589}
.type-cap b{display:block;font-family:var(--ff-head);font-weight:600;color:var(--navy);font-size:.7rem;letter-spacing:.1em;text-transform:uppercase;margin-bottom:3px}
.after-grid{margin-top:clamp(26px,2.8vw,40px);margin-bottom:0}

/* ---------- steps ---------- */
.steps{counter-reset:s;display:grid;grid-template-columns:repeat(4,1fr);gap:clamp(20px,2.6vw,38px);list-style:none;padding:0;margin:0}
.steps li{counter-increment:s;margin:0;padding:clamp(26px,2.4vw,34px) clamp(22px,2vw,28px);position:relative;
  background:rgba(255,255,255,.045);border:1px solid rgba(255,255,255,.1);border-radius:var(--r-card);
  transition:background-color var(--t) var(--ease),border-color var(--t) var(--ease),transform var(--t) var(--ease)}
.steps li:hover{background:rgba(255,255,255,.075);border-color:rgba(255,255,255,.2);transform:translateY(-3px)}
.steps li::before{content:"0" counter(s);font-family:var(--ff-head);font-weight:600;font-size:1.06rem;line-height:1;
  letter-spacing:.04em;color:#fff;display:grid;place-items:center;width:46px;height:46px;border-radius:50%;
  background:var(--red);margin-bottom:20px;box-shadow:0 10px 22px -10px rgba(203,66,54,.9)}
.steps li:nth-child(even)::before{background:var(--navy-600);box-shadow:0 10px 22px -10px rgba(43,74,140,.9)}
.steps h3{font-size:1.12rem;margin-bottom:.5em}
.steps p{font-size:.93rem;margin:0;color:var(--d-body)}

/* ---------- hairline grids (brands, areas) ---------- */
.hgrid{display:grid;gap:1px;background:var(--line);border:1px solid var(--line);border-radius:var(--r-lg);overflow:hidden;list-style:none;margin:0;padding:0}
.hgrid li{margin:0}
.hgrid a{display:flex;height:100%;background:#fff;text-decoration:none;transition:background-color var(--t) var(--ease),color var(--t) var(--ease)}
.brands{grid-template-columns:repeat(6,1fr)}
.brands a{flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:4px;padding:30px 14px;min-height:118px;font-family:var(--ff-head);font-weight:600;font-size:1.14rem;color:var(--navy);letter-spacing:.01em;text-transform:uppercase}
.brands a span{font-family:var(--ff-body);font-weight:400;font-size:.75rem;color:var(--muted);line-height:1.4;text-transform:none;letter-spacing:0}
.brands a:hover{background:var(--navy-900);color:#fff}
.brands a:hover span{color:var(--d-muted)}
.areas{grid-template-columns:repeat(4,1fr);margin-bottom:28px}
.areas a{align-items:center;gap:.7em;padding:22px 24px;font-family:var(--ff-head);font-weight:600;font-size:.99rem;color:var(--ink);min-height:70px}
.areas .ic{color:#fff;background:var(--navy);border-radius:50%;padding:7px;width:30px;height:30px;box-sizing:border-box;flex:none;transition:background-color var(--t) var(--ease),transform var(--t) var(--ease)}
.areas a:hover{background:var(--navy-900);color:#fff}
.areas a:hover .ic{background:var(--red);transform:translateX(2px)}
.areas-note{margin:0;max-width:72ch}

/* ---------- reasons ---------- */
.reasons{list-style:none;padding:0;margin:0}
.reasons{display:grid;gap:clamp(10px,1.1vw,14px)}
.reasons li{display:grid;grid-template-columns:38px 1fr;gap:18px;margin:0;padding:clamp(18px,1.8vw,24px) clamp(18px,1.8vw,24px);
  background:#fff;border:1px solid var(--line);border-radius:var(--r-card);
  transition:border-color var(--t) var(--ease),box-shadow var(--t) var(--ease),transform var(--t) var(--ease)}
.reasons li:hover{border-color:transparent;box-shadow:var(--sh-2);transform:translateX(3px)}
.reasons .ic-md{color:#fff;background:var(--navy);border-radius:var(--r-sm);padding:9px;width:38px;height:38px;box-sizing:border-box;margin-top:1px}
.reasons li:nth-child(even) .ic-md{background:var(--red)}
.reasons h3{font-size:1.08rem;margin-bottom:.3em}
.reasons p{font-size:.95rem;margin:0}
.b-navy .reasons li{background:rgba(255,255,255,.05);border-color:rgba(255,255,255,.12)}
.b-navy .reasons li:hover{background:rgba(255,255,255,.08);border-color:rgba(255,255,255,.22);box-shadow:none}
.b-navy .reasons .ic-md{background:var(--red)}
.b-navy .reasons li:nth-child(even) .ic-md{background:var(--navy-600)}

/* ---------- commercial lists ---------- */
.g2{display:grid;grid-template-columns:repeat(2,1fr);gap:clamp(22px,2.4vw,40px)}
.g2>div{background:#fff;border:1px solid var(--line);border-radius:var(--r-card);padding:clamp(26px,2.6vw,38px)}
.checks{list-style:none;padding:0;margin:0}
.checks{display:grid;gap:8px}
.checks li{display:grid;grid-template-columns:24px 1fr;gap:14px;margin:0;padding:13px 15px;font-size:.95rem;line-height:1.6;
  background:var(--paper-2);border-radius:var(--r);transition:background-color var(--t) var(--ease)}
.checks li:hover{background:var(--navy-50)}
.checks .ic{color:#fff;background:var(--red);border-radius:50%;padding:6px;width:24px;height:24px;box-sizing:border-box;margin-top:4px}
.col-head{font-size:1.1rem;margin-bottom:.7em}

/* ---------- table ---------- */
.tbl-wrap{border:1px solid var(--line);border-radius:var(--r-lg);background:#fff;overflow:hidden;box-shadow:var(--sh-1)}
.tbl-scroll{overflow-x:auto}
table{width:100%;border-collapse:collapse;min-width:640px}
caption{text-align:center;padding:24px 20px 22px;font-family:var(--ff-head);font-weight:600;color:var(--ink);font-size:1.1rem;border-bottom:1px solid var(--line);text-transform:uppercase;letter-spacing:.06em}
th,td{text-align:left;padding:17px 22px;border-bottom:1px solid var(--line);font-size:.94rem;vertical-align:top;line-height:1.62}
thead th{background:var(--navy-900);color:#fff;font-family:var(--ff-head);font-weight:600;font-size:.74rem;letter-spacing:.14em;text-transform:uppercase;border-bottom:0}
tbody tr:nth-child(even){background:var(--paper-2)}
tbody tr:hover{background:var(--navy-50)}
tbody tr:last-child th,tbody tr:last-child td{border-bottom:0}
tbody th{font-family:var(--ff-head);font-weight:600;color:var(--ink);width:24%}

/* ---------- faq: brand panel over a tinted band ---------- */
.faq-layout{display:grid;grid-template-columns:minmax(0,.82fr) minmax(0,1.18fr);gap:clamp(28px,3.6vw,64px);align-items:start}
.faq-layout .sec-head{margin-bottom:0;align-self:start;padding-top:clamp(0px,1.6vw,22px)}
.faq{background:var(--navy-900);border:0;border-radius:var(--r-lg);overflow:hidden;box-shadow:var(--sh-3);position:relative}
.faq-item{position:relative;z-index:1}
.faq-item+.faq-item{border-top:1px solid rgba(255,255,255,.14)}
.faq h3{margin:0;font-size:inherit;letter-spacing:0;text-transform:none}
.faq-q{width:100%;display:flex;align-items:flex-start;justify-content:space-between;gap:22px;text-align:left;background:none;border:0;cursor:pointer;padding:24px clamp(20px,2.2vw,32px);font-family:var(--ff-head);font-weight:600;font-size:clamp(1rem,1.15vw,1.1rem);color:#fff;line-height:1.48;transition:background-color var(--t) var(--ease)}
.faq-q:hover{background:rgba(255,255,255,.07)}
.faq-q .ic{flex:none;width:30px;height:30px;padding:8px;border-radius:50%;background:rgba(255,255,255,.14);color:#fff;box-sizing:border-box;margin-top:1px;transition:transform var(--t) var(--ease),background-color var(--t) var(--ease)}
.faq-q:hover .ic{background:var(--red)}
.faq-q[aria-expanded="true"] .ic{transform:rotate(45deg);background:var(--red)}
.faq-a{padding:0 clamp(20px,2.2vw,32px) 26px;display:none;max-width:74ch;color:var(--d-body)}
.faq-a.open{display:block}
.faq-a p{color:var(--d-body);font-size:.95rem}
.faq-a p:last-child{margin-bottom:0}

/* ---------- forms ---------- */
.form-card{background:#fff;border:1px solid var(--line);border-radius:var(--r-lg);padding:clamp(26px,3vw,42px);box-shadow:var(--sh-3)}
.b-navy .form-card h3{color:var(--ink)}
.b-navy .form-card p{color:var(--muted)}
.form-card>h3{margin-bottom:.35em;font-size:1.3rem}
.form-card>p{font-size:.89rem;color:var(--muted);margin-bottom:1.6em}
.fgrid{display:grid;grid-template-columns:repeat(2,1fr);gap:17px}
.field{display:flex;flex-direction:column;gap:7px}
.field.full{grid-column:1/-1}
.field label{font-family:var(--ff-head);font-weight:600;font-size:.87rem;color:var(--ink)}
.b-navy .form-card label{color:var(--ink)}
.field .req{color:var(--red-700)}
.field input,.field select,.field textarea{font-family:var(--ff-body);font-size:1rem;color:var(--ink);background:var(--paper-2);border:1.5px solid var(--line);border-radius:var(--r);padding:13px 16px;width:100%;min-height:52px;transition:border-color var(--t) var(--ease),background-color var(--t) var(--ease),box-shadow var(--t) var(--ease)}
.field textarea{min-height:124px;resize:vertical}
.field input::placeholder,.field textarea::placeholder{color:#99a2b3}
.field input:focus,.field select:focus,.field textarea:focus{border-color:var(--navy);background:#fff;outline:3px solid rgba(32,56,110,.16);outline-offset:0}
.field input[aria-invalid="true"],.field select[aria-invalid="true"],.field textarea[aria-invalid="true"]{border-color:var(--red-700);background:var(--red-50)}
.err{font-size:.84rem;color:var(--red-700);font-weight:600;display:none;align-items:center;gap:.35em}
.err.show{display:flex}
.form-foot{margin-top:22px;display:flex;flex-wrap:wrap;align-items:center;gap:16px}
.form-foot p{margin:0;font-size:.85rem;color:var(--muted)}
.b-navy .form-card .form-foot p{color:var(--muted)}
.b-navy .form-card a{color:var(--navy)}
.b-navy .form-card a:hover{color:var(--red-700)}

/* ---------- quote drawer + floating controls ---------- */
.q-backdrop{position:fixed;inset:0;background:rgba(8,13,26,.66);z-index:95;display:none}
.q-backdrop.open{display:block}
#global-quick-quote{position:fixed;top:0;right:0;height:100%;width:min(492px,100%);background:var(--paper-2);z-index:96;display:none;flex-direction:column;box-shadow:-28px 0 70px -24px rgba(8,13,26,.7);border:0;padding:0;margin:0;max-width:100%;max-height:100%;overflow:hidden}
#global-quick-quote.open{display:flex}
.q-head{position:relative;display:flex;align-items:flex-start;justify-content:space-between;gap:16px;padding:26px var(--gut);background:var(--navy-900);color:#fff;overflow:hidden}
.q-head>*{position:relative;z-index:1}
.q-title{font-family:var(--ff-head);font-weight:600;font-size:1.3rem;color:#fff;margin:0 0 5px;letter-spacing:.02em;text-transform:uppercase}
.q-head p{margin:0;font-size:.88rem;color:var(--d-body)}
.q-close{background:rgba(255,255,255,.14);border:0;color:#fff;width:46px;height:46px;border-radius:50%;cursor:pointer;display:grid;place-items:center;flex:none;transition:background-color var(--t) var(--ease),transform var(--t) var(--ease)}
.q-close:hover{background:var(--red);transform:rotate(90deg)}
.q-body{padding:0;overflow-y:auto;flex:1}
.q-body .fgrid{grid-template-columns:1fr}
@media (min-width:440px){.q-body .fgrid{grid-template-columns:repeat(2,1fr)}}
.body-lock{overflow:hidden}
.to-top{position:fixed;right:22px;bottom:94px;z-index:84;width:50px;height:50px;border-radius:50%;background:#fff;border:1.5px solid var(--line-2);color:var(--navy);cursor:pointer;display:none;place-items:center;box-shadow:var(--sh-2);transition:background-color var(--t) var(--ease),color var(--t) var(--ease),border-color var(--t) var(--ease)}
.to-top.show{display:grid}
.to-top:hover{background:var(--navy);color:#fff;border-color:var(--navy)}
.floating-hidden{display:none!important}

/* ---------- footer ---------- */
.site-footer{position:relative;background:#070c18;color:var(--d-body);font-size:.94rem;overflow:hidden}
.site-footer>*{position:relative;z-index:1}
.site-footer h3{font-family:var(--ff-head);font-size:.8rem;letter-spacing:.17em;text-transform:uppercase;color:#fff;margin:0 0 18px;font-weight:600}
.site-footer h3.after-grid{margin-top:30px}
.site-footer ul{list-style:none;margin:0;padding:0}
.site-footer li{margin-bottom:0}
.site-footer a{color:var(--d-body);text-decoration:none;display:inline-block;min-height:34px;padding-block:6px;line-height:1.5;transition:color var(--t) var(--ease)}
.site-footer a:hover{color:#fff;text-decoration:underline}
.f-grid{display:grid;grid-template-columns:1.6fr 1fr 1fr 1.25fr;gap:clamp(28px,3vw,56px);padding-block:clamp(52px,6vw,88px) clamp(40px,4.4vw,64px);align-items:start}
.f-brand img{width:182px;margin-bottom:22px;background:#fff;padding:11px 14px;border-radius:var(--r)}
.f-brand p{max-width:40ch;color:var(--d-muted)}
.site-footer .f-contact{background:rgba(255,255,255,.055);border:1px solid var(--line-dark);border-radius:var(--r-card);padding:18px 20px}
.f-contact li{display:flex;gap:.7em;align-items:flex-start;min-height:34px}
.f-contact li+li{margin-top:6px}
.f-contact span{padding-block:6px;min-width:0}
.f-contact a,.f-contact span{overflow-wrap:anywhere}
.f-contact .ic{color:#fff;background:var(--red);border-radius:50%;padding:6px;width:26px;height:26px;box-sizing:border-box;margin-top:7px;flex:none}
.f-brands{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));column-gap:14px}
.socials{display:flex;flex-wrap:wrap;gap:10px;margin-top:24px}
.socials a{width:44px;height:44px;border-radius:50%;background:rgba(255,255,255,.09);display:grid;place-items:center;color:#fff;min-height:0;padding:0;transition:background-color var(--t) var(--ease),transform var(--t) var(--ease)}
.socials a:hover{background:var(--red);transform:translateY(-3px)}
.f-bar{border-top:1px solid rgba(255,255,255,.08);padding-top:24px;padding-bottom:clamp(82px,7vw,96px);display:flex;flex-wrap:wrap;gap:10px 30px;justify-content:space-between;align-items:center;font-size:.85rem;color:var(--d-muted)}
.f-bar p{margin:0}
.f-bar ul{display:flex;flex-wrap:wrap;gap:2px 24px}
.f-bar li{margin:0}
.f-bar a{min-height:30px;padding-block:4px}
.built{display:inline-flex;align-items:center;gap:8px;white-space:nowrap;color:var(--d-muted)}
.built img{width:20px;height:20px;flex:none;border-radius:var(--r-xs)}
.built b{color:#fff;font-family:var(--ff-head);font-weight:600}

/* ---------- scroll reveal ---------- */
.js .rv{opacity:0;transform:translateY(18px);transition:opacity .6s var(--ease),transform .6s var(--ease)}
.js .rv.in{opacity:1;transform:none}

/* ---------- responsive ---------- */
@media (max-width:1180px){
  .hero-grid{grid-template-columns:1fr}
  .hero h1{max-width:20ch}
  .hero .fig figcaption{position:static;width:auto;margin-top:0;backdrop-filter:none}
  .hero .media{position:relative;inset:auto;height:auto}
  .hero .fig{border-radius:var(--r-lg);box-shadow:var(--sh-3);height:auto}
  .hero .fig img{aspect-ratio:16/10;height:auto}
  .hero .media::after{border-radius:var(--r-lg);background:linear-gradient(180deg,rgba(10,16,30,.12),rgba(10,16,30,.42))}
  .hero{background:var(--navy-900)}
  .hero::after{content:"";position:absolute;inset:0;pointer-events:none;z-index:0;background:radial-gradient(62% 72% at 6% 0%,rgba(43,74,140,.55),transparent 62%),radial-gradient(48% 56% at 100% 100%,rgba(203,66,54,.26),transparent 64%)}
  .hero .media{z-index:1}
  .faq-layout{grid-template-columns:1fr}
}
@media (max-width:1100px){
  .types{grid-template-columns:repeat(2,1fr)}
  .steps{grid-template-columns:repeat(2,1fr);gap:30px}
  .brands{grid-template-columns:repeat(3,1fr)}
  .f-grid{grid-template-columns:repeat(2,1fr)}
  .proof{grid-template-columns:repeat(2,1fr)}
  .proof li:nth-child(-n+2){border-bottom:1px solid var(--line)}
  .proof li:nth-child(odd){border-left:0}
  .sec-head.split{grid-template-columns:1fr;align-items:start;gap:18px}
  .sec-head.split .lede{padding-bottom:0}
}
@media (max-width:860px){
  .split,.g2{grid-template-columns:1fr}
  .split .media{order:-1}
  .split.media-first .media{order:0}
  .areas{grid-template-columns:repeat(2,1fr)}
}
@media (max-width:760px){.hero{--hdr-bar:103px}}
@media (max-width:660px){.hero{--hdr-bar:89px}}
@media (max-width:720px){
  body{font-size:16px}
  .svc-grid{grid-template-columns:1fr}
  .hero-actions .btn{flex:1 1 100%}
  .fgrid{grid-template-columns:1fr}
    tbody th{width:auto}
  .hdr{padding-block:11px}
}
@media (max-width:560px){
  .types{grid-template-columns:1fr}
  .steps{grid-template-columns:1fr;gap:26px}
  .brands{grid-template-columns:repeat(2,1fr)}
  .proof{grid-template-columns:1fr}
  .proof li{border-left:0;border-bottom:1px solid var(--line)}
  .proof li:last-child{border-bottom:0}
  .areas{grid-template-columns:1fr}
  .f-grid{grid-template-columns:1fr}
  .f-bar{justify-content:flex-start}
  .to-top{right:12px;bottom:82px}
  table{min-width:520px}
  th,td{padding:14px 16px}
  .b-round,.b-round-b{border-radius:var(--r-lg) var(--r-lg) 0 0}
  .b-round-b{border-radius:0 0 var(--r-lg) var(--r-lg)}
}
@media (prefers-reduced-motion:reduce){
  *{animation-duration:.01ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important}
  .btn:hover,.svc:hover,.type:hover,.socials a:hover{transform:none}
  .type:hover .type-media img{transform:none}
  .btn:hover .bdg,.q-close:hover{transform:none}
  .js .rv{opacity:1;transform:none}
}
@media print{
  .site-header,.utility,.q-dock,.to-top,.q-backdrop,#global-quick-quote{display:none!important}
  body{font-size:12pt;color:#000}
  .js .rv{opacity:1;transform:none}
}

/* ============================================================
   v4 additions: real site imagery, brand logo strip with the
   Request a Quote badge, and the fixed side quote tab.
   ============================================================ */

/* ---------- hero: photographic bed + branded figure ---------- */
.hero .fig figcaption{display:none}
.hero .media::after{background:
  linear-gradient(90deg,rgba(7,12,24,.94) 0%,rgba(7,12,24,.8) 30%,rgba(7,12,24,.4) 55%,rgba(7,12,24,.18) 100%),
  linear-gradient(180deg,rgba(7,12,24,.72) 0%,transparent 26%,rgba(7,12,24,.6) 100%)}
.hero-figure{position:relative;z-index:2;align-self:end;display:flex;justify-content:center;margin-bottom:calc(var(--panel-drop) * -1 - 6px);--panel-drop:clamp(38px,5vw,64px)}
.hero-figure::before{content:"";position:absolute;z-index:0;bottom:6%;left:50%;transform:translateX(-50%);
  width:min(104%,460px);aspect-ratio:1;border-radius:50%;
  background:radial-gradient(circle at 50% 50%,var(--navy-600) 0%,var(--navy-700) 46%,rgba(27,47,92,0) 71%)}
.hero-figure::after{content:"";position:absolute;z-index:0;bottom:6%;left:50%;transform:translateX(-50%);
  width:min(104%,460px);aspect-ratio:1;border-radius:50%;border:1.5px solid rgba(232,119,108,.45)}
.hero-figure img{position:relative;z-index:1;width:min(100%,430px);height:auto;filter:drop-shadow(0 34px 46px rgba(5,9,20,.6))}
@media (max-width:1180px){
  .hero-figure{display:none}
  .hero .media{position:absolute;inset:0;z-index:0;height:auto}
  .hero .fig{border-radius:0;box-shadow:none;height:100%}
  .hero .fig img{aspect-ratio:auto;height:100%;object-position:62% 46%}
  .hero .media::after{border-radius:0;background:
    linear-gradient(180deg,rgba(7,12,24,.86) 0%,rgba(7,12,24,.62) 38%,rgba(7,12,24,.74) 72%,rgba(7,12,24,.88) 100%)}
  .hero::before,.hero::after{content:none}
}

/* ---------- proof strip back inside the hero ---------- */
.proof{background:none;border-radius:0;box-shadow:none;transform:none;margin:0;overflow:visible;
  border-top:1px solid var(--line-dark);position:relative;z-index:3}

.proof li{border-left:1px solid var(--line-dark);color:#dde4f3;padding:24px clamp(16px,2vw,30px) 26px}
.proof li:first-child{border-left:0;padding-left:0}
.proof b{color:#fff}
.proof .ic-md{background:var(--red);color:#fff}
.proof li:nth-child(odd) .ic-md{background:var(--navy-600)}
.after-hero{padding-top:var(--band)}
@media (max-width:1100px){
  .proof li:nth-child(-n+2){border-bottom:0}
  .proof li:nth-child(odd){border-left:0}
  .proof li:nth-child(n+3){border-top:1px solid var(--line-dark)}
}
@media (max-width:560px){
  .proof li,.proof li:nth-child(n+3){border-left:0;border-bottom:0;border-top:1px solid var(--line-dark);padding:18px 0}
  .proof li:first-child{border-top:0}
}

/* ---------- brand logo strip riding the hero edge ---------- */
.brandstrip{position:relative;z-index:6;margin-top:clamp(-56px,-3.4vw,-34px);margin-bottom:clamp(14px,2vw,26px)}
.bs-panel{position:relative;background:#fff;border-radius:var(--r-xl);box-shadow:var(--sh-3);
  padding:clamp(44px,4.2vw,58px) clamp(20px,3vw,48px) clamp(26px,3vw,40px)}
.bs-list{display:grid;grid-template-columns:repeat(6,1fr);align-items:center;gap:clamp(14px,2vw,30px);
  list-style:none;margin:0;padding:0}
.bs-list li{margin:0;display:flex;align-items:center;justify-content:center;min-height:64px}
.bs-list a{display:flex;align-items:center;justify-content:center;width:100%;height:100%;text-decoration:none;
  padding:6px 4px;border-radius:var(--r-sm);transition:transform var(--t) var(--ease),opacity var(--t) var(--ease)}
.bs-list img{max-height:60px;max-width:88%;width:auto;object-fit:contain;opacity:.92;
  transition:opacity var(--t) var(--ease),transform var(--t) var(--ease)}
.bs-list a:hover{transform:translateY(-3px)}
.bs-list a:hover img{opacity:1}
.bs-word{font-family:var(--ff-head);font-weight:700;font-size:clamp(1.02rem,1.4vw,1.34rem);letter-spacing:.05em;
  text-transform:uppercase;color:var(--navy);transition:color var(--t) var(--ease)}
.bs-list a:hover .bs-word{color:var(--red-700)}
.bs-badge{position:absolute;top:0;left:50%;width:clamp(104px,9vw,122px);height:clamp(104px,9vw,122px);
  transform:translate(-50%,-54%);background:#fff;border-radius:50%;padding:0;z-index:4;border:0;cursor:pointer;
  display:grid;place-items:center;box-shadow:0 18px 40px -18px rgba(13,20,38,.55)}
.bs-badge-inner{position:relative;width:58%;height:58%;border-radius:50%;background:var(--red);display:grid;place-items:center;
  transition:background-color var(--t) var(--ease),transform var(--t) var(--ease);box-shadow:0 14px 30px -12px rgba(203,66,54,.9)}
.bs-badge:hover .bs-badge-inner{background:var(--navy);transform:scale(1.04)}
.bs-badge .arrow{width:26px;height:26px;fill:#fff;transform:rotate(45deg);transition:transform var(--t) var(--ease)}
.bs-badge:hover .arrow{transform:rotate(0deg)}
.bs-ring{position:absolute;inset:0;width:100%;height:100%;animation:bs-spin 18s linear infinite}

.bs-ring text{font-family:var(--ff-head);font-size:10.4px;font-weight:600;letter-spacing:.2em;fill:var(--navy);text-transform:uppercase}
.bs-badge:hover .bs-ring text{fill:var(--red-700)}
@keyframes bs-spin{to{transform:rotate(360deg)}}
@media (max-width:1100px){
  .bs-list{grid-template-columns:repeat(3,1fr);gap:18px 10px}
  .bs-panel{padding-top:clamp(52px,7vw,64px)}
}
@media (max-width:560px){
  .bs-list{grid-template-columns:repeat(2,1fr)}
  .bs-list img{max-height:38px}
  .brandstrip{margin-top:clamp(-46px,-6vw,-30px)}
}

/* ---------- fixed side quote tab ---------- */
.q-dock{position:fixed;right:0;top:50%;transform:translateY(-50%);z-index:86;width:62px;height:308px}
.q-tab{position:relative;display:block;width:62px;height:308px;border:0;padding:0;margin:0;cursor:pointer;
  background:linear-gradient(180deg,var(--navy-700) 0%,var(--navy-900) 64%);border-radius:var(--r-sm) 0 0 var(--r-sm);
  box-shadow:-10px 0 34px -14px rgba(5,9,20,.85);transition:background var(--t) var(--ease)}
.q-tab:hover{background:linear-gradient(180deg,var(--navy-600) 0%,var(--navy-800) 64%)}
@keyframes q-pulse{0%,100%{opacity:.85;transform:scaleY(.94)}50%{opacity:1;transform:scaleY(1.06)}}
.q-tab-text{position:absolute;left:0;right:0;top:12px;bottom:66px;display:flex;align-items:center;justify-content:center;
  writing-mode:vertical-rl;text-orientation:mixed;font-family:var(--ff-head);font-weight:700;font-size:.93rem;
  letter-spacing:.21em;text-transform:uppercase;color:#fff;white-space:nowrap}
.q-tab-text em{font-style:normal;color:var(--red-300)}
.q-tab-go{position:absolute;left:0;right:0;bottom:0;height:60px;background:var(--red);display:grid;place-items:center;
  border-radius:0 0 0 var(--r-sm);transition:background-color var(--t) var(--ease)}
.q-tab-go::after{content:"";position:absolute;left:0;right:0;bottom:-7px;height:8px;background:var(--red);
  -webkit-mask:repeating-linear-gradient(90deg,#000 0 6px,transparent 6px 12px);
  mask:repeating-linear-gradient(90deg,#000 0 6px,transparent 6px 12px)}
.q-tab:hover .q-tab-go,.q-tab:hover .q-tab-go::after{background:var(--red-700)}
.q-tab-go svg{width:19px;height:19px;fill:#fff;transition:transform var(--t) var(--ease)}
.q-tab:hover .q-tab-go svg{transform:translateX(3px)}
.q-flyout{position:absolute;right:62px;top:50%;transform:translateY(-50%) translateX(14px);width:290px;
  background:var(--navy-900);color:var(--d-body);border-radius:var(--r) 0 0 var(--r);padding:20px 22px;
  box-shadow:-18px 0 44px -18px rgba(5,9,20,.85);opacity:0;visibility:hidden;pointer-events:none;
  transition:opacity var(--t) var(--ease),transform var(--t) var(--ease),visibility var(--t) var(--ease)}
.q-dock:hover .q-flyout,.q-dock.flyout-open .q-flyout{opacity:1;visibility:visible;transform:translateY(-50%) translateX(0)}
.q-dock.flyout-off .q-flyout{opacity:0!important;visibility:hidden!important;transform:translateY(-50%) translateX(14px)!important}
.q-flyout ul{list-style:none;margin:0;padding:0}
.q-flyout li{display:grid;grid-template-columns:26px 1fr;gap:12px;margin:0;font-size:.85rem;line-height:1.5;padding:11px 0;
  border-top:1px solid var(--line-dark)}
.q-flyout li:first-child{border-top:0;padding-top:0}
.q-flyout li:last-child{padding-bottom:0}
.q-flyout .ic{width:26px;height:26px;padding:7px;border-radius:50%;background:var(--red);color:#fff;box-sizing:border-box}
.q-flyout b{display:block;color:#fff;font-family:var(--ff-head);font-weight:600;font-size:.88rem;margin-bottom:1px}
@media (max-width:1100px){.q-flyout{display:none}}

/* below this width the tab would sit over hero copy, so it becomes a compact launcher (same drawer) */
@media (max-width:860px){
  .q-dock{top:auto;right:0;left:0;bottom:0;transform:none;width:100%;height:auto}
  .q-tab,.q-flyout{display:none}
