  .bs-ring{animation:none}
  }

/* ---------- commercial media ---------- */
.commercial-split{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(0,.92fr);gap:clamp(24px,2.8vw,44px);align-items:start}
