  --t:.24s; --t-slow:.55s; --ease:cubic-bezier(.4,.16,.2,1);
}
.nifty-part-header-1 *, .nifty-part-header-1 *::before, .nifty-part-header-1 *::after {box-sizing:border-box}
.nifty-part-header-1 {-webkit-text-size-adjust:100%;scroll-behavior:smooth}
.nifty-part-header-1 {margin:0;background:var(--paper);color:var(--body);font-family:var(--ff-body);font-size:17px;line-height:1.72;overflow-x:hidden;-webkit-font-smoothing:antialiased}
.nifty-part-header-1 h1, .nifty-part-header-1 h2, .nifty-part-header-1 h3, .nifty-part-header-1 h4 {font-family:var(--ff-head);color:var(--ink);margin:0 0 .5em;font-weight:500}
