.nifty-part-header-1 .ic-md {width:20px;height:20px;flex:none;fill:currentColor}
.nifty-part-header-1 .ic-lg {width:24px;height:24px;flex:none;fill:currentColor}
.nifty-part-header-1 .wrap {width:100%;max-width:var(--maxw);margin-inline:auto;padding-inline:var(--gut)}
