.nifty-part-header-1 .skip:focus {left:0}
.nifty-part-header-1 section[id] {scroll-margin-top:104px}
.nifty-part-header-1 .eyebrow {display:flex;align-items:center;gap:.6em;font-family:var(--ff-head);font-size:.8rem;font-weight:600;letter-spacing:.2em;text-transform:uppercase;color:var(--navy);margin:0 0 1.05rem}
.nifty-part-header-1 .eyebrow::before {content:"";width:22px;height:22px;flex:none;border-radius:50%;background:var(--red);
  -webkit-mask:radial-gradient(circle at 50% 50%,transparent 0 3.6px,#000 3.6px);
