.nifty-part-header-1 .sec-head.split {display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);gap:clamp(24px,3.4vw,64px);align-items:end;max-width:none}
.nifty-part-header-1 .sec-head.split h2 {margin-bottom:0}
