.nifty-part-header-1 .btn {position:relative;display:inline-flex;align-items:center;justify-content:center;gap:.7em;font-family:var(--ff-head);font-weight:600;font-size:.98rem;line-height:1.2;letter-spacing:.015em;padding:14px 22px 14px 28px;border-radius:var(--r-pill);border:1.5px solid transparent;cursor:pointer;text-decoration:none;min-height:58px;overflow:hidden;isolation:isolate;transition:background-color var(--t) var(--ease),border-color var(--t) var(--ease),color var(--t) var(--ease),transform var(--t) var(--ease),box-shadow var(--t) var(--ease)}
.nifty-part-header-1 .btn .ic {position:relative;z-index:1}
