.nifty-part-header-1 .btn .bdg {position:relative;z-index:1;width:32px;height:32px;border-radius:50%;display:grid;place-items:center;flex:none;margin-left:.1em;transition:transform var(--t) var(--ease),background-color var(--t) var(--ease),color var(--t) var(--ease)}
.nifty-part-header-1 .btn .bdg svg {width:13px;height:13px;fill:currentColor}
.nifty-part-header-1 .btn:hover .bdg {transform:rotate(-45deg)}
.nifty-part-header-1 .btn-primary {background:var(--red);color:#fff;border-color:var(--red);box-shadow:0 12px 26px -12px rgba(203,66,54,.85)}
.nifty-part-header-1 .btn-primary .bdg {background:#fff;color:var(--red)}
